package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.jsoup.nodes.Attribute#getValue
 */
public class Attribute_getValue_TriageGen2Test {













    @Test
    public void testGetValue_AfterClone() {
        String key = "title";
        String value = "hello";
        Attribute original = new Attribute(key, value);
        Attribute cloned = original.clone();

        assertEquals("Cloned attribute should have the same value as the original", value, cloned.getValue());
        assertNotSame("Cloned attribute should be a different object instance", original, cloned);
    }
}
